import fs from 'node:fs';import postcss from 'postcss';
const ast=postcss.parse(fs.readFileSync('src/styles.css','utf8'));
const tokenNames=new Set();ast.walkRules(r=>{if(r.selector?.includes(':root'))r.walkDecls(d=>{if(d.prop.startsWith('--'))tokenNames.add(d.prop)})});
const demo=/\.(?:atelier|topbar|board-|sidebar-|catalog-|widget-catalog-page|radial-|type-weight-|type-contrast-|demo-|intro-|foundation-|specimen|swatch|type-(?:display|body|mono)|spacing-demo|edge-demo|motion-tokens|surface-stack|surface-sample|settings-stack|overlay-mini|mini-window|sheet-mini|command-teaser|energy-state|window-lab|window-dock|window-canvas-etch)/;
const utility=/^\.(?:row|between|end|wrap|stack|small|muted|mono|display|eyebrow|danger-text|tiny-square)(?:[ >:+.\[]|$)/;
ast.walkRules(r=>{if(r.parent.type==='atrule'&&/keyframes/.test(r.parent.name))return;const selectors=r.selectors.filter(s=>!demo.test(s)&&(!/^(?:\*|html|body|button|input|textarea|select|a|svg|h[1-6]|p|code|::selection)(?:$|[,:+>\[ ])/.test(s)||s.includes(':root')||s.includes('.nb-')));if(!selectors.length){r.remove();return}r.selectors=selectors.map(s=>{s=s.replaceAll('data-theme','data-nbrain-theme').replaceAll('data-density','data-nbrain-density').replaceAll('data-motion','data-nbrain-motion');if(s.includes('[data-nbrain-motion=off]')&&s.includes('*'))s=s.replace(/\*(?=[: ]|$)/g,':is(.nb-root,.nb-root *,.nb-dialog,.nb-dialog *,.nb-popup,.nb-popup *,.nb-toast,.nb-toast *)');if(s.startsWith(':root'))return s.replace(':root',':root[data-nbrain-ui]');if(s.includes('[data-nbrain-motion=off]')&&s.includes('*'))s=s.replace(/\*(?=[: ]|$)/g,':is(.nb-root,.nb-root *,.nb-dialog,.nb-dialog *,.nb-popup,.nb-popup *,.nb-toast,.nb-toast *)');if(utility.test(s))return ':where([data-nbrain-ui]) :is(.nb-root,.nb-dialog,.nb-popup,.nb-toast) '+s;return ':where([data-nbrain-ui]) '+s})});
ast.walkDecls(d=>{for(const name of tokenNames){const renamed='--nb-'+name.slice(2);if(d.prop===name)d.prop=renamed;d.value=d.value.replaceAll('var('+name+')','var('+renamed+')').replaceAll('var('+name+',','var('+renamed+',')}});
ast.walkAtRules(a=>{if(a.nodes?.length===0)a.remove()});
ast.walkAtRules(a=>{if(/keyframes/.test(a.name))a.params='nb-'+a.params});ast.walkDecls(d=>{if(/animation/.test(d.prop))d.value=d.value.replace(/\b(spin|shimmer|popup-in|status-pulse)\b/g,'nb-$1')});
let css=ast.toString();css+='\n:where([data-nbrain-ui]) :is(.nb-root,.nb-dialog,.nb-popup,.nb-tooltip,.nb-toast){font-family:var(--nb-font-sans);font-size:14px;line-height:1.55;color:var(--nb-foreground)}\n:where([data-nbrain-ui]) :is(.nb-button,.nb-input,.nb-select,.nb-menu-item){font-family:var(--nb-font-sans)}\n';
css+='\n@media(prefers-reduced-motion:reduce){:where([data-nbrain-ui]) :is(.nb-root,.nb-root *,.nb-dialog,.nb-dialog *,.nb-popup,.nb-popup *,.nb-toast,.nb-toast *){animation-duration:.01ms!important;animation-iteration-count:1!important;transition-duration:.01ms!important}}\n:where([data-nbrain-ui]) :is(.nb-dialog,.nb-popup,.nb-toast) *{box-sizing:border-box}\n:where([data-nbrain-ui]) :is(.nb-dialog,.nb-popup,.nb-toast) :is(h1,h2,h3,p){margin:0}\n';
fs.mkdirSync('.build',{recursive:true});fs.writeFileSync('.build/styles.css',css);console.log('Isolated package CSS: '+Buffer.byteLength(css)+' bytes');
